from typing import Any

import httpx
from fastmcp import FastMCP


def build_mcp_server(
    openapi_spec: dict[str, Any],
    client: httpx.AsyncClient,
    name: str = "OpenAPI Server",
) -> FastMCP:
    """Generate an MCP server whose tools mirror an OpenAPI specification.

    Args:
        openapi_spec: Minimal OpenAPI 3.0 specification as a dict.
        client: httpx.AsyncClient configured with the API base URL.
        name: Name for the generated MCP server.

    Returns:
        A FastMCP server instance with tools derived from the spec.
    """
    return FastMCP.from_openapi(
        openapi_spec=openapi_spec,
        client=client,
        name=name,
    )


OPENAPI_SPEC: dict[str, Any] = {
    "openapi": "3.0.0",
    "info": {"title": "Example API", "version": "1.0.0"},
    "paths": {
        "/items/{item_id}": {
            "get": {
                "operationId": "get_item",
                "summary": "Get an item by ID",
                "parameters": [
                    {
                        "name": "item_id",
                        "in": "path",
                        "required": True,
                        "schema": {"type": "integer"},
                    }
                ],
                "responses": {"200": {"description": "OK"}},
            }
        }
    },
}


def main() -> None:
    client = httpx.AsyncClient(base_url="https://api.example.com")
    mcp = build_mcp_server(OPENAPI_SPEC, client)
    mcp.run()


if __name__ == "__main__":
    main()

